head.script:
//
  (function(){
    var DEFAULTS={theme:'dark',accent:'lime',custom:'#b6f06a',bg:'grid',motion:'off',font:'inter',measure:'standard',size:100,focus:false};
    var PRESETS={
      lime:{dark:'#b6f06a',light:'#3f7d12'},
      teal:{dark:'#5eecd0',light:'#0b7a68'},
      amber:{dark:'#f7c75a',light:'#8f5c00'},
      violet:{dark:'#b9a2ff',light:'#5b3fc4'},
      coral:{dark:'#ff9a80',light:'#b8432a'}
    };
    function ink(hex){
      var n=parseInt(hex.slice(1),16), r=(n>>16)&255, g=(n>>8)&255, b=n&255;
      return (0.2126*r+0.7152*g+0.0722*b)>150 ? '#0a1409' : '#ffffff';
    }
    function pick(v,allowed,fallback){ return allowed.indexOf(v)!==-1 ? v : fallback; }
    function normalize(s){
      var o={}, k;
      for(k in DEFAULTS){ o[k]=DEFAULTS[k]; }
      if(s && typeof s==='object'){
        for(k in s){ if(Object.prototype.hasOwnProperty.call(DEFAULTS,k)){ o[k]=s[k]; } }
      }
      o.theme=pick(o.theme,['dark','light','oled','paper'],'dark');
      o.accent=pick(o.accent,['lime','teal','amber','violet','coral','custom'],'lime');
      if(typeof o.custom!=='string' || !/^#[0-9a-f]{6}$/i.test(o.custom)) o.custom='#b6f06a';
      o.bg=pick(o.bg,['grid','dots','diagonal','noise','aurora','solid'],'grid');
      o.motion=pick(o.motion,['off','subtle','full'],'off');
      o.font=pick(o.font,['inter','plex','serif','system'],'inter');
      o.measure=pick(o.measure,['narrow','standard','wide'],'standard');
      o.size=Math.max(85,Math.min(130,parseInt(o.size,10)||100));
      o.focus=!!o.focus;
      return o;
    }
    function load(){
      var raw=null;
      try{ raw=localStorage.getItem('as-settings'); }catch(e){}
      if(raw){ try{ return normalize(JSON.parse(raw)); }catch(e){} }
      /* One-time migration from the v6 keys */
      var legacy={};
      try{
        var t=localStorage.getItem('as-theme');
        if(t==='light'||t==='dark') legacy.theme=t;
        var z=parseInt(localStorage.getItem('as-global-size'),10);
        if(z) legacy.size=z;
        if(localStorage.getItem('as-focus')==='1') legacy.focus=true;
      }catch(e){}
      return normalize(legacy);
    }
    function apply(s){
      var r=document.documentElement, light=(s.theme==='light'||s.theme==='paper');
      r.setAttribute('data-theme',s.theme);
      r.setAttribute('data-bg',s.bg);
      r.setAttribute('data-motion',s.motion);
      r.setAttribute('data-font',s.font);
      r.setAttribute('data-measure',s.measure);
      r.style.setProperty('--reader-scale',String(s.size/100));
      r.classList.toggle('focus-mode',s.focus);
      var acc = s.accent==='custom' ? s.custom : PRESETS[s.accent][light?'light':'dark'];
      r.style.setProperty('--accent',acc);
      r.style.setProperty('--accent-ink',ink(acc));
      r.style.colorScheme = light ? 'light' : 'dark';
    }
    window.AS_DEFAULTS=DEFAULTS;
    window.AS_NORMALIZE=normalize;
    window.AS_APPLY=apply;
    window.AS=load();
    apply(window.AS);
  })();
  //

head.b:skin:
/* ==========================================================
   ASTRALSURGE v7.1: dark-first engineering journal
   Tokens → base → components → display options → responsive
   ========================================================== */

/* ---------- 1. Tokens ---------- */
:root{
  --font:Inter,system-ui,-apple-system,"Segoe UI",sans-serif;
  --body-font:var(--font);
  --mono:"JetBrains Mono",ui-monospace,SFMono-Regular,Menlo,monospace;
  --radius:16px;--max:1240px;--reading:740px;--post-lh:1.9;
  --accent:#b6f06a;--accent-ink:#0a1409;
  --grid:color-mix(in srgb,var(--accent) 5%,transparent);
  --grid-strong:color-mix(in srgb,var(--accent) 16%,transparent);
  --shadow-sm:0 1px 2px rgba(0,0,0,.08);
  --shadow-lg:0 18px 40px rgba(0,0,0,.22);
  color-scheme:dark;
}
:root,:root[data-theme="dark"]{
  --bg:#0a0f0e;--surface:#111a18;--surface-2:#162220;
  --border:#22302c;--border-strong:#2f4541;
  --text:#e9efe9;--muted:#8c9d96;--link:#7fd6bf;
}
:root[data-theme="light"]{
  --bg:#f6f7f3;--surface:#ffffff;--surface-2:#eef1ea;
  --border:#dde3da;--border-strong:#c7d0c4;
  --text:#101815;--muted:#5d6b65;--link:#0c6b5a;
  --shadow-lg:0 18px 40px rgba(16,24,21,.14);
  color-scheme:light;
}
:root[data-theme="oled"]{
  --bg:#000000;--surface:#0a0a0a;--surface-2:#131313;
  --border:#1f1f1f;--border-strong:#2e2e2e;
  --text:#f2f2f2;--muted:#8a8a8a;--link:#8fe3cc;
}
:root[data-theme="paper"]{
  --bg:#f3ecdc;--surface:#fbf7ee;--surface-2:#ece3cf;
  --border:#d9ceb4;--border-strong:#c4b696;
  --text:#2a2118;--muted:#6e604c;--link:#2f6b5e;
  --shadow-lg:0 18px 40px rgba(42,33,24,.14);
  color-scheme:light;
}
:root[data-font="plex"]{--font:"IBM Plex Sans",system-ui,sans-serif;--mono:"IBM Plex Mono",ui-monospace,monospace}
:root[data-font="serif"]{--body-font:"Source Serif 4",Georgia,serif}
:root[data-font="system"]{--font:system-ui,-apple-system,"Segoe UI",sans-serif;--mono:ui-monospace,SFMono-Regular,Menlo,monospace}
:root[data-measure="narrow"]{--reading:640px;--post-lh:1.8}
:root[data-measure="standard"]{--reading:740px;--post-lh:1.9}
:root[data-measure="wide"]{--reading:880px;--post-lh:1.75}

/* ---------- 2. Base ---------- */
*,*::before,*::after{box-sizing:border-box}
[hidden]{display:none!important}
html{scroll-behavior:smooth;scroll-padding-top:90px;font-size:calc(100% * var(--reader-scale,1));-webkit-text-size-adjust:100%}
body{margin:0;font:400 .97rem/1.65 var(--font);color:var(--text);background:var(--bg);-webkit-font-smoothing:antialiased;min-height:100vh}
a{color:var(--link);text-decoration:none;transition:color .15s}
a:hover{color:var(--accent)}
img{max-width:100%;height:auto;display:block}
button{font:inherit}
:focus-visible{outline:2px solid var(--accent);outline-offset:3px;border-radius:4px}
.wrap{max-width:var(--max);margin:0 auto;padding:0 24px}
.visually-hidden{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}
h1,h2,h3{text-wrap:balance}

/* ---------- 3. Backgrounds (fixed layers behind content) ---------- */
body::before{content:"";position:fixed;inset:0;z-index:-2;pointer-events:none}
body::after{content:"";position:fixed;inset:-25%;z-index:-1;pointer-events:none;opacity:0;
  background:
    radial-gradient(closest-side at 30% 40%,color-mix(in srgb,var(--accent) 22%,transparent),transparent),
    radial-gradient(closest-side at 72% 62%,color-mix(in srgb,var(--link) 20%,transparent),transparent)}
[data-bg="grid"] body::before{background-image:linear-gradient(var(--grid) 1px,transparent 1px),linear-gradient(90deg,var(--grid) 1px,transparent 1px);background-size:44px 44px}
[data-bg="dots"] body::before{background-image:radial-gradient(var(--grid-strong) 1px,transparent 1.3px);background-size:22px 22px}
[data-bg="diagonal"] body::before{background-image:repeating-linear-gradient(45deg,var(--grid) 0 1px,transparent 1px 16px)}
[data-bg="noise"] body::before{opacity:1;background-image:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='160' height='160'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='.85' numOctaves='2' stitchTiles='stitch'/><feColorMatrix values='0 0 0 0 .5  0 0 0 0 .5  0 0 0 0 .5  0 0 0 .08 0'/></filter><rect width='100%' height='100%' filter='url(%23n)'/></svg>")}
[data-bg="aurora"] body::before{background:linear-gradient(160deg,var(--bg),var(--surface-2))}
[data-bg="aurora"] body::after{opacity:1}
[data-bg="solid"] body::before{background:none}

/* ---------- 4. Ambient motion (off by default) ---------- */
[data-motion="subtle"][data-bg="aurora"] body::after{animation:as-drift 46s ease-in-out infinite alternate}
[data-motion="full"][data-bg="aurora"] body::after{animation:as-drift 20s ease-in-out infinite alternate}
[data-motion="full"][data-bg="dots"] body::before{animation:as-dots 24s linear infinite}
[data-motion="subtle"] .hero::before,[data-motion="full"] .hero::before{opacity:.7;animation:as-sweep 9s ease-in-out infinite}
[data-motion="subtle"] .hero-glow,[data-motion="full"] .hero-glow{opacity:1}
[data-motion="full"] .art-glow{animation:as-pulse 5s ease-in-out infinite}
@keyframes as-drift{from{transform:translate3d(-3%,-2%,0) scale(1)}to{transform:translate3d(4%,3%,0) scale(1.08)}}
@keyframes as-dots{to{background-position:220px 220px}}
@keyframes as-sweep{0%{transform:translateX(-100%)}60%,100%{transform:translateX(420%)}}
@keyframes as-pulse{50%{opacity:.3}}
html.is-hidden body::before,html.is-hidden body::after,html.is-hidden .hero::before,html.is-hidden .art-glow{animation-play-state:paused!important}
@media (prefers-reduced-motion:reduce){
  body::before,body::after,.hero::before,.art-glow{animation:none!important}
  .hero-glow{display:none}
}

/* ---------- 5. Header ---------- */
.top{position:sticky;top:0;z-index:50;backdrop-filter:saturate(1.4) blur(14px);-webkit-backdrop-filter:saturate(1.4) blur(14px);background:color-mix(in srgb,var(--bg) 90%,transparent);border-bottom:1px solid var(--border)}
.top .wrap{display:flex;align-items:center;gap:16px;height:66px}
.brand{display:flex;align-items:center;gap:12px;min-width:0;color:var(--text);font-weight:800;letter-spacing:-.02em;font-size:1.02rem;overflow:hidden;white-space:nowrap;text-overflow:ellipsis}
.brand:hover{color:var(--text)}
.brand-mark{width:32px;height:32px;flex:0 0 32px;border-radius:10px;background:var(--accent);color:var(--accent-ink);display:grid;place-items:center;font:800 .7rem var(--mono);box-shadow:0 0 0 4px color-mix(in srgb,var(--accent) 12%,transparent)}
.main-nav{margin-left:auto}
.main-nav ul{display:flex;gap:4px;list-style:none;margin:0;padding:0}
.main-nav a{display:block;color:var(--muted);font-size:.9rem;font-weight:500;padding:9px 13px;border-radius:9px;transition:background .18s,color .18s}
.main-nav a:hover,.main-nav a[aria-current="page"]{color:var(--text);background:var(--surface-2)}
.icon-btn{width:36px;height:36px;flex:0 0 auto;border:1px solid var(--border);background:transparent;color:var(--muted);border-radius:9px;cursor:pointer;display:grid;place-items:center;font-size:15px;transition:color .15s,border-color .15s}
.icon-btn:hover{color:var(--text);border-color:var(--border-strong)}
.nav-toggle{display:none}

/* ---------- 6. Site tools bar + settings panel ---------- */
.site-tools{border-bottom:1px solid var(--border);background:color-mix(in srgb,var(--bg) 88%,var(--surface))}
.site-tools-inner{max-width:var(--max);margin:0 auto;padding:10px 24px;display:flex;align-items:center;gap:10px;flex-wrap:wrap}
.site-follow{display:flex;align-items:center;gap:10px;padding-left:16px;border-left:1px solid var(--border);font-size:.8rem;color:var(--muted)}
.site-follow a{color:var(--text);font-weight:600}
.site-follow a:hover{color:var(--accent)}

.settings{position:fixed;top:124px;right:max(16px,calc((100vw - var(--max)) / 2 + 24px));z-index:80;width:min(360px,calc(100vw - 32px));max-height:calc(100vh - 140px);overflow:auto;padding:18px 18px 16px;border:1px solid var(--border-strong);border-radius:16px;background:var(--surface);box-shadow:var(--shadow-lg)}
.settings-head{display:flex;align-items:center;justify-content:space-between;margin:0 0 4px;font-weight:700}
.opt{border:0;padding:0;margin:16px 0 0;min-width:0}
.opt legend{font:600 .68rem var(--mono);letter-spacing:.09em;text-transform:uppercase;color:var(--muted);margin:0 0 8px;padding:0}
.chips{display:flex;flex-wrap:wrap;gap:6px}
.chip{appearance:none;display:inline-flex;align-items:center;gap:6px;min-height:32px;padding:5px 11px;border:1px solid var(--border-strong);border-radius:999px;background:var(--bg);color:var(--text);font:600 .8rem var(--font);cursor:pointer;transition:border-color .15s,background .15s,color .15s}
.chip:hover{border-color:var(--accent)}
.chip[aria-pressed="true"]{background:var(--accent);color:var(--accent-ink);border-color:var(--accent)}
.swatch{width:12px;height:12px;border-radius:50%;background:var(--sw);box-shadow:0 0 0 1px rgba(0,0,0,.25)}
.chip-color{position:relative}
.chip-color input{width:24px;height:24px;padding:0;border:0;background:none;cursor:pointer}
.stepper{display:flex;align-items:center;gap:8px}
.stepper output{min-width:52px;text-align:center;font:600 .85rem var(--mono)}
.note{font-size:.76rem;color:var(--muted);margin:8px 0 0}
.settings-foot{display:flex;gap:8px;margin-top:16px;padding-top:14px;border-top:1px solid var(--border)}
.settings-foot .chip{flex:1;justify-content:center}

/* ---------- 7. Hero (homepage) ---------- */
.hero{display:grid;grid-template-columns:1.02fr .98fr;align-items:center;gap:26px;position:relative;isolation:isolate;min-height:272px;padding:34px 36px;margin:28px 0 20px;border:1px solid var(--border-strong);border-radius:var(--radius);overflow:hidden;background:radial-gradient(ellipse at 78% 50%,color-mix(in srgb,var(--accent) 16%,transparent),transparent 48%),linear-gradient(120deg,var(--surface),var(--bg))}
.hero::after{content:"";position:absolute;inset:0;z-index:-1;opacity:.5;pointer-events:none;background:repeating-linear-gradient(145deg,transparent 0 40px,color-mix(in srgb,var(--accent) 8%,transparent) 41px,transparent 42px 78px)}
.hero::before{content:"";position:absolute;top:0;bottom:0;left:0;width:30%;z-index:1;pointer-events:none;opacity:0;background:linear-gradient(90deg,transparent,color-mix(in srgb,var(--accent) 16%,transparent),transparent)}
.hero-glow{position:absolute;inset:0;z-index:0;pointer-events:none;opacity:0;transition:opacity .4s;background:radial-gradient(circle 240px at var(--mx,70%) var(--my,50%),color-mix(in srgb,var(--accent) 18%,transparent),transparent 70%)}
.hero-copy{position:relative;z-index:2}
.kicker{display:inline-flex;align-items:center;gap:8px;font:600 .72rem var(--mono);letter-spacing:.07em;text-transform:uppercase;color:var(--accent);margin:0 0 14px}
.kicker:before{content:"";width:6px;height:6px;border-radius:50%;background:var(--accent);box-shadow:0 0 12px var(--accent)}
.hero h1{font-size:clamp(2rem,3.2vw,2.85rem);line-height:1.04;letter-spacing:-.045em;font-weight:800;margin:0 0 14px;max-width:15ch}
.hero h1 em{font-style:normal;color:var(--accent)}
.hero .lede{font-size:.98rem;line-height:1.55;color:var(--muted);max-width:47ch;margin:0 0 18px}
.hero-topics ul{display:flex;flex-wrap:wrap;gap:8px;list-style:none;margin:0;padding:0}
.hero-topics a{display:inline-flex;padding:7px 13px;border:1px solid var(--border-strong);border-radius:999px;font-size:.85rem;font-weight:500;color:var(--text);background:var(--surface);transition:transform .18s,border-color .18s,color .18s}
.hero-topics a:hover{border-color:var(--accent);color:var(--accent);transform:translateY(-2px)}
.hero-art{height:220px;position:relative;min-width:0;z-index:1}
.art-glow{position:absolute;width:68%;height:65%;left:17%;top:18%;background:var(--accent);filter:blur(45px);opacity:.13;border-radius:50%}
.art-laptop{position:absolute;width:53%;height:66%;left:32%;top:20%;transform:rotate(-8deg) skewY(1deg);filter:drop-shadow(0 18px 16px rgba(0,0,0,.5))}
.laptop-screen{position:absolute;inset:0 0 13% 0;border:3px solid color-mix(in srgb,var(--accent) 55%,#000);border-radius:8px;background:linear-gradient(145deg,var(--surface-2),var(--bg) 75%);padding:15px 12px;overflow:hidden}
.laptop-screen b,.laptop-screen i{display:block;height:3px;margin:8px 0;border-radius:3px;background:var(--accent);opacity:.7}
.laptop-screen i:nth-of-type(2){width:83%;margin-left:8%}
.laptop-screen i:nth-of-type(3){width:72%;margin-left:15%}
.laptop-screen i:nth-of-type(4){width:90%;margin-left:3%}
.laptop-screen span{position:absolute;right:12%;bottom:17%;width:25%;height:24%;border:1px solid var(--accent);border-radius:4px}
.laptop-base{position:absolute;left:-8%;right:-8%;bottom:0;height:16%;background:linear-gradient(180deg,var(--surface-2),var(--border-strong));clip-path:polygon(8% 0,92% 0,100% 100%,0 100%);border-radius:0 0 9px 9px}
.art-server{position:absolute;left:12%;top:38%;width:22%;height:43%;transform:skewY(-8deg);border:1px solid var(--border-strong);border-radius:8px;background:linear-gradient(135deg,var(--surface-2),var(--surface));padding:17px 10px}
.art-server i{display:block;height:4px;margin:9px 0;background:var(--accent);border-radius:3px;opacity:.8}
.art-server span{position:absolute;right:9px;bottom:10px;width:9px;height:9px;border-radius:50%;background:var(--accent)}
.art-chip{position:absolute;z-index:2;display:grid;place-items:center;width:50px;height:48px;border:1px solid var(--accent);border-radius:9px;background:var(--surface);color:var(--accent);font:700 1.1rem var(--mono)}
.chip-ai{left:40%;top:5%}
.chip-code{right:7%;top:12%;font-size:1rem}
.art-cloud{position:absolute;right:7%;bottom:7%;font-size:2rem;color:var(--accent);opacity:.8}

/* ---------- 8. Search, section heads, tags, meta ---------- */
.search{position:relative;margin:0 0 20px;max-width:100%}
.search input{width:100%;height:50px;padding:0 44px 0 16px;border:1px solid var(--border-strong);border-radius:999px;background:var(--surface);color:var(--text);font:inherit;font-size:.95rem;outline:none;transition:border-color .15s,box-shadow .15s}
.search input:focus{border-color:var(--accent);box-shadow:0 0 0 3px color-mix(in srgb,var(--accent) 22%,transparent)}
.search kbd{position:absolute;right:14px;top:50%;transform:translateY(-50%);font:500 .72rem var(--mono);color:var(--muted);border:1px solid var(--border-strong);border-radius:6px;padding:2px 6px;pointer-events:none}
.sec-head{display:flex;align-items:baseline;justify-content:space-between;gap:16px;margin:0 0 12px;padding:0 0 12px;border-bottom:1px solid var(--border)}
.sec-head h2{margin:0;font-size:1.2rem;font-weight:700;letter-spacing:-.02em}
.view-all{display:inline-flex;gap:7px;color:var(--muted);font-size:.84rem;font-weight:600}
.view-all:hover{color:var(--accent)}
.view-all span{transition:transform .18s}
.view-all:hover span{transform:translateX(3px)}
.tag{align-self:flex-start;max-width:100%;overflow-wrap:anywhere;font:500 .7rem var(--mono);text-transform:uppercase;letter-spacing:.08em;color:var(--accent);padding:5px 9px;border:1px solid color-mix(in srgb,var(--accent) 35%,transparent);border-radius:6px}
.meta{font-size:.82rem;color:var(--muted);display:flex;gap:10px;flex-wrap:wrap;align-items:center}
.meta-note{font-size:.9rem;color:var(--muted);margin:0 0 16px}

/* ---------- 9. Story lists (homepage grid, archive rows) ---------- */
.grid{display:flex;flex-direction:column;gap:12px;margin:0;padding:0;list-style:none}
.card{display:grid;grid-template-columns:minmax(180px,34%) minmax(0,1fr);min-height:164px;border:1px solid var(--border);border-radius:12px;background:var(--surface);overflow:hidden;transition:transform .22s,border-color .22s,box-shadow .22s;min-width:0}
.card-img{display:block;position:relative;min-height:150px;height:100%;overflow:hidden;background:radial-gradient(circle at 80% 15%,color-mix(in srgb,var(--accent) 18%,transparent),transparent 40%),linear-gradient(135deg,var(--surface-2),var(--bg))}
.card-img img{width:100%;height:100%;object-fit:cover;transition:transform .45s cubic-bezier(.2,.7,.2,1)}
.card-body{padding:17px 20px;display:flex;flex-direction:column;gap:8px;flex:1;min-width:0}
.card h2{margin:0;font-size:1.17rem;line-height:1.3;letter-spacing:-.025em;overflow-wrap:anywhere}
.card h2 a{color:var(--text)}
.card h2 a:hover{color:var(--accent)}
.card p{margin:0;color:var(--muted);font-size:.9rem;line-height:1.65;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
.card .meta{margin-top:auto;padding-top:4px}
.card:hover,.feature:hover{transform:translateY(-3px);border-color:var(--accent);box-shadow:var(--shadow-lg)}
.card:hover .card-img img,.feature:hover .feature-img img{transform:scale(1.025)}
/* Posts without a featured image: drop the image column so no empty box is drawn */
.card.no-img,.feature.no-img{grid-template-columns:minmax(0,1fr)!important;min-height:0}
.card.no-img .card-img,.feature.no-img .feature-img{display:none!important}
.card.no-img .card-body{padding:20px 22px}
.feature.no-img .feature-body{padding:clamp(22px,3vw,40px)}

.home-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px;margin:0;padding:0;list-style:none}
.home-grid>.feature{grid-column:1/-1;display:grid;grid-template-columns:minmax(0,1.15fr) minmax(0,.85fr);align-items:stretch;min-width:0;border:1px solid var(--border);border-radius:18px;overflow:hidden;background:var(--surface);box-shadow:var(--shadow-sm);transition:transform .22s,border-color .22s,box-shadow .22s}
.feature-img{display:block;position:relative;min-width:0;aspect-ratio:16/9;overflow:hidden;background:var(--surface-2)}
.feature-img img{width:100%;height:100%;object-fit:cover;transition:transform .35s ease}
.feature-body{min-width:0;padding:clamp(22px,3vw,42px);display:flex;flex-direction:column;justify-content:center;gap:14px}
.feature h2{margin:0;font-size:clamp(1.4rem,2.4vw,2.2rem);line-height:1.16;letter-spacing:-.04em;overflow-wrap:anywhere}
.feature h2 a{color:var(--text)}
.feature h2 a:hover{color:var(--accent)}
.feature p{margin:0;color:var(--muted);font-size:.94rem;line-height:1.7;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
.home-grid>.card{display:flex;flex-direction:column;min-height:0;border-radius:var(--radius)}
.home-grid>.card .card-img{aspect-ratio:16/9;min-height:0;height:auto;flex:0 0 auto}
.home-grid>.card .card-body{padding:20px;gap:12px}
.home-grid>.card h2{font-size:1.06rem;line-height:1.4}
.home-grid>.card p{font-size:.9rem;line-height:1.65}

.blog-pager{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;margin:40px 0 0}
.blog-pager a{display:inline-flex;align-items:center;min-height:42px;padding:10px 17px;border:1px solid var(--border-strong);border-radius:999px;background:var(--surface);color:var(--text);font-size:.88rem;font-weight:600;transition:transform .18s,border-color .18s,color .18s}
.blog-pager a:hover{border-color:var(--accent);color:var(--accent);transform:translateY(-2px)}
.blog-pager .blog-pager-older-link{margin-left:auto}

/* ---------- 10. Article ---------- */
.article{width:100%;max-width:var(--reading);margin:0 auto}
.crumbs{font:500 .78rem var(--mono);color:var(--muted);margin:48px 0 18px}
.crumbs a{color:var(--muted)}
.crumbs a:hover{color:var(--accent)}
.article h1{margin:0 0 18px;font-size:clamp(2.1rem,5vw,3.5rem);line-height:1.05;letter-spacing:-.06em;font-weight:800;overflow-wrap:anywhere}
.article-meta{display:flex;flex-wrap:wrap;gap:8px 12px;color:var(--muted);font-size:.86rem;line-height:1.6;padding-bottom:22px;margin-bottom:24px;border-bottom:1px solid var(--border)}
.toolbar{position:sticky;top:66px;z-index:20;display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin:0 0 28px;padding:8px 0;background:color-mix(in srgb,var(--bg) 92%,transparent);backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px);border-bottom:1px solid color-mix(in srgb,var(--border) 70%,transparent)}
.tool-group{display:inline-flex;align-items:center;gap:4px;padding:4px;border:1px solid var(--border-strong);border-radius:999px;background:var(--surface)}
.tool-btn{appearance:none;display:inline-flex;align-items:center;justify-content:center;min-height:32px;padding:4px 12px;border:1px solid var(--border-strong);border-radius:999px;background:transparent;color:var(--text);font:600 .8rem var(--font);cursor:pointer;transition:color .15s,border-color .15s,background .15s}
.tool-btn:hover{color:var(--accent);border-color:var(--accent)}
.tool-btn[aria-pressed="true"]{background:var(--accent);color:var(--accent-ink);border-color:var(--accent)}
.tool-group .tool-btn{border:0}

.share{display:flex;flex-wrap:wrap;align-items:center;gap:6px;margin:0 0 28px}
.share-label{font:600 .72rem var(--mono);text-transform:uppercase;letter-spacing:.08em;color:var(--muted);margin-right:4px}
.share a,.share button{appearance:none;display:inline-flex;align-items:center;justify-content:center;min-height:32px;padding:5px 11px;border:1px solid var(--border-strong);border-radius:999px;background:var(--surface);color:var(--text);font:600 .78rem var(--font);cursor:pointer;text-decoration:none;transition:border-color .15s,color .15s}
.share a:hover,.share button:hover{border-color:var(--accent);color:var(--accent)}
.site-share{margin:0;flex:1;min-width:260px}
.site-share a,.site-share button{background:transparent}
.share a.ic,.share button.ic{width:36px;height:36px;min-height:36px;padding:0;border-radius:50%}
.share a.ic svg,.share button.ic svg{width:16px;height:16px;display:block;pointer-events:none}
.share-bottom{margin:40px 0 0;padding-top:24px;border-top:1px solid var(--border)}

.post-body{font-family:var(--body-font);font-size:1.08rem;line-height:var(--post-lh);overflow-wrap:anywhere;min-width:0}
.post-body p,.post-body ul,.post-body ol{margin:0 0 1.2em}
.post-body li{margin:.35em 0}
.post-body h2{margin:2.2em 0 .6em;padding-bottom:10px;border-bottom:1px solid var(--border);font-size:clamp(1.5rem,3vw,2rem);line-height:1.15;letter-spacing:-.045em;scroll-margin-top:100px}
.post-body h3{margin:1.7em 0 .5em;font-size:1.25rem;letter-spacing:-.02em;scroll-margin-top:100px}
.post-body a{text-decoration:underline;text-underline-offset:3px;text-decoration-thickness:1px}
.post-body :not(pre)>code{padding:.12em .38em;border:1px solid var(--border);border-radius:5px;background:var(--surface-2);font:.87em var(--mono)}
.post-body pre{position:relative;max-width:100%;overflow:auto;margin:1.6em 0;padding:22px 18px;border:1px solid var(--border);border-radius:14px;background:#06100e;color:#e4f2eb;font:400 .84rem/1.7 var(--mono);tab-size:2}
.post-body pre code{padding:0;background:none;border:0;font:inherit;white-space:pre}
.copy-code{position:absolute;top:9px;right:9px;padding:5px 10px;border:1px solid var(--border-strong);border-radius:8px;background:var(--surface-2);color:var(--text);font:600 .72rem var(--font);cursor:pointer}
.copy-code:hover{border-color:var(--accent);color:var(--accent)}
.post-body blockquote{margin:1.5em 0;padding:16px 20px;border-left:3px solid var(--accent);background:var(--surface);border-radius:0 12px 12px 0}
.post-body img{margin:1.5em auto;border-radius:12px;cursor:zoom-in}
.post-body table{display:block;width:100%;overflow-x:auto;border-collapse:collapse;margin:1.5em 0;font-size:.9rem}
.post-body th,.post-body td{padding:10px 12px;border:1px solid var(--border);text-align:left;vertical-align:top}
.post-body th{background:var(--surface-2)}
.post-body iframe,.post-body video,.post-body embed{max-width:100%}

.article-toc{margin:0 0 30px;padding:18px 20px;border:1px solid var(--border);border-radius:14px;background:var(--surface)}
.article-toc summary{cursor:pointer;font-weight:700}
.article-toc ol{margin:10px 0 0;padding-left:20px}
.article-toc li{padding:3px 0;font-size:.9rem}
.article-toc a{color:var(--text);overflow-wrap:anywhere}
.article-toc a.is-active{color:var(--accent)}
.post-labels{display:flex;flex-wrap:wrap;gap:8px;margin:44px 0 0;padding-top:24px;border-top:1px solid var(--border)}
.post-labels a{padding:6px 11px;border:1px solid var(--border-strong);border-radius:999px;font-size:.78rem;color:var(--text);background:var(--surface);transition:border-color .15s,color .15s}
.post-labels a:hover{border-color:var(--accent);color:var(--accent)}
.author-box{margin:40px 0 0;padding:20px;border:1px solid var(--border);border-radius:14px;background:var(--surface)}
.post-nav{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin:36px 0 0}
.post-nav a{display:flex;flex-direction:column;gap:4px;padding:18px;border:1px solid var(--border);border-radius:14px;background:var(--surface);color:var(--text);transition:transform .18s,border-color .18s}
.post-nav a:hover{border-color:var(--accent);transform:translateY(-2px)}
.post-nav a span{color:var(--muted);font:500 .72rem var(--mono);text-transform:uppercase}
.post-nav-next{text-align:right}

/* ---------- 11. Comments ---------- */
.comments{margin-top:56px;padding-top:30px;border-top:1px solid var(--border)}
.comments-title{margin:0 0 18px;font-size:1.25rem}
.comment-block{padding:14px 0;border-bottom:1px solid var(--border)}
.comment-author{font-weight:700;font-size:.92rem;margin-bottom:4px}
.comment-body{font-size:.93rem}
.comment-timestamp{color:var(--muted);font-size:.78rem}
.avatar-image-container{float:left;overflow:hidden;width:34px;height:34px;margin:0 12px 0 0;border-radius:50%}
.avatar-image-container img{width:34px;height:34px}
#comment-editor{width:100%;min-height:120px;border:0}

/* ---------- 12. Layout + sidebar ---------- */
.layout{display:grid;grid-template-columns:minmax(0,1fr) 290px;gap:clamp(28px,4.5vw,64px);align-items:start;padding:40px 0 80px}
#main-col{min-width:0}
.sidebar{position:sticky;top:90px;min-width:0}
.sidebar .widget{margin:0 0 20px;padding:20px;background:linear-gradient(145deg,var(--surface),color-mix(in srgb,var(--surface) 86%,var(--accent)));border:1px solid var(--border);border-radius:14px;box-shadow:var(--shadow-sm)}
.sidebar h2.title{margin:0 0 14px;font:700 .95rem var(--font);letter-spacing:-.02em;color:var(--text)}
.sidebar ul{list-style:none;margin:0;padding:0}
.sidebar li{padding:9px 0;border-bottom:1px solid var(--border);font-size:.9rem}
.sidebar li:last-child{border-bottom:0}
.sidebar li a{display:inline-block;transition:transform .15s,color .15s}
.sidebar li a:hover{transform:translateX(3px)}
.label-count,.post-count{margin-left:4px;color:var(--muted);font-size:.8em}
.pop-item{display:flex;gap:10px;align-items:flex-start;padding:10px 0;border-bottom:1px solid var(--border)}
.pop-item:last-child{border-bottom:0}
.pop-thumb{flex:0 0 60px;width:60px;height:60px;border-radius:7px;object-fit:cover;background:var(--surface-2)}
.pop-title{margin:0;font-size:.9rem;font-weight:600;line-height:1.35}
.pop-title a{color:var(--text)}
.pop-date{font-size:.75rem;color:var(--muted)}
.sidebar .search-form{display:flex;flex-direction:column;gap:8px}
.sidebar .search-form input{height:42px;padding:0 12px;border:1px solid var(--border-strong);border-radius:999px;background:var(--bg);color:var(--text);font:inherit}
.sidebar .search-form button{height:42px;border:0;border-radius:999px;background:var(--accent);color:var(--accent-ink);font-weight:700;cursor:pointer}
.follow-card p{margin:0 0 12px;color:var(--muted);font-size:.9rem}
.follow-card a.btn{display:inline-flex;padding:9px 14px;border-radius:999px;background:var(--accent);color:var(--accent-ink);font-weight:700;font-size:.86rem}

/* Focus mode hides the sidebar and widens the column */
html.focus-mode .sidebar{display:none}
html.focus-mode .layout{grid-template-columns:minmax(0,1fr)}
html.focus-mode .hero,html.focus-mode .sec-head,html.focus-mode .site-follow{display:none}

/* ---------- 13. Utilities ---------- */
.reading-progress{position:fixed;top:0;left:0;right:0;height:2px;z-index:60;pointer-events:none}
.reading-progress span{display:block;width:0;height:100%;background:var(--accent);transition:width .08s linear}
.to-top{position:fixed;right:22px;bottom:22px;width:42px;height:42px;border-radius:12px;border:1px solid var(--border-strong);background:var(--surface);color:var(--text);cursor:pointer;opacity:0;pointer-events:none;transition:opacity .2s;font-size:16px;box-shadow:var(--shadow-sm);z-index:45}
.to-top.show{opacity:1;pointer-events:auto}
.to-top:hover{border-color:var(--accent);color:var(--accent)}
.toast{position:fixed;left:50%;bottom:24px;transform:translate(-50%,20px);max-width:calc(100vw - 32px);padding:11px 16px;border-radius:12px;background:var(--surface);border:1px solid var(--border-strong);color:var(--text);font-size:.88rem;text-align:center;opacity:0;pointer-events:none;transition:opacity .2s,transform .2s;z-index:90}
.toast.show{opacity:1;transform:translate(-50%,0)}
.lightbox{border:0;padding:0;background:transparent;max-width:min(96vw,1200px)}
.lightbox::backdrop{background:rgba(0,0,0,.85)}
.lightbox img{max-height:90vh;width:auto;margin:0 auto;border-radius:12px;cursor:zoom-out}

footer{border-top:1px solid var(--border);padding:40px 0 56px;color:var(--muted);font-size:.88rem;margin-top:16px}
footer .wrap{display:flex;flex-wrap:wrap;justify-content:space-between;gap:20px}
footer ul{display:flex;gap:18px;flex-wrap:wrap;list-style:none;margin:0;padding:0}
footer a{color:var(--muted)}
footer a:hover{color:var(--accent)}
footer .title{display:none}

/* ---------- 14. Responsive ---------- */
@media(max-width:1000px){
  .layout{grid-template-columns:minmax(0,1fr)}
  .sidebar{position:static;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}
  .sidebar .widget{margin:0}
}
@media(max-width:960px){
  .home-grid{grid-template-columns:repeat(2,minmax(0,1fr))}
  .home-grid>.card:nth-child(4){grid-column:1/-1}
  .home-grid>.feature{grid-template-columns:minmax(0,1fr)}
  .main-nav{display:none}
  .nav-toggle{display:grid;margin-left:auto}
  .top.nav-open .main-nav{display:block;position:absolute;left:0;right:0;top:66px;background:var(--bg);border-bottom:1px solid var(--border);padding:12px 24px}
  .top.nav-open .main-nav ul{flex-direction:column;align-items:stretch}
}
@media(min-width:761px) and (max-width:1179px){
  .home-grid{grid-template-columns:repeat(2,minmax(0,1fr))}
}
@media(max-width:760px){
  .hero{grid-template-columns:1fr;padding:22px 20px;gap:4px;margin:16px 0;min-height:0}
  .hero-art{height:150px;max-width:440px;width:100%;margin:0 auto}
  .hero h1{font-size:clamp(2rem,8vw,2.6rem)}
  .home-grid{grid-template-columns:minmax(0,1fr);gap:16px}
  .home-grid>.feature{grid-column:1}
  .home-grid>.card:nth-child(4){grid-column:auto}
  .card,.feature{grid-template-columns:1fr}
  .card-img{min-height:0;aspect-ratio:16/9}
  .feature-body,.card-body{padding:20px}
  .post-nav{grid-template-columns:1fr}
  .post-nav-next{text-align:left}
  .site-share{min-width:0;flex-basis:100%}
  .site-follow{margin-left:auto;border-left:0;padding-left:0}
  .settings{right:16px;top:118px}
}
@media(max-width:620px){
  .wrap{padding-left:18px;padding-right:18px}
  .top .wrap{height:62px}
  .top.nav-open .main-nav{top:62px}
  .toolbar{top:62px;gap:6px}
  .tool-btn{min-height:34px;padding:4px 9px;font-size:.76rem}
  .post-body{font-size:1rem}
  .post-body pre{padding:38px 13px 16px;font-size:.78rem}
  .copy-code{top:7px;right:7px}
  .article-toc{padding:15px}
  .share a,.share button{padding:6px 10px}
  .to-top{right:14px;bottom:14px}
  .sidebar{grid-template-columns:minmax(0,1fr)}
}
@media(prefers-reduced-motion:reduce){
  *,*::before,*::after{transition-duration:.01ms!important;scroll-behavior:auto!important}
  .card:hover,.feature:hover{transform:none}
}


/* ---------- AstralSurge responsive enhancement patch (review build) ---------- */
/* Keep desktop geometry intact; compact dense widgets only at mobile widths. */
@media (max-width:760px){
  .wrap{padding-inline:16px}
  .top .wrap{gap:10px}
  .brand{font-size:.96rem;gap:9px}
  .brand-mark{width:30px;height:30px;flex-basis:30px}
  .hero{padding:18px 16px;margin:12px 0 14px;gap:8px}
  .hero-art{height:112px}
  .search{margin-bottom:14px}
  .search input{height:46px}
  .sidebar{gap:10px}
  .sidebar .widget{padding:14px;margin:0}
  .sidebar h2.title{margin-bottom:8px}
  .sidebar li{padding:7px 0;font-size:.88rem;line-height:1.4}
  .post-body{overflow-wrap:anywhere}
  .post-body pre{max-width:100%;overflow-x:auto;overscroll-behavior-x:contain;-webkit-overflow-scrolling:touch}
  .post-body table{overscroll-behavior-x:contain;-webkit-overflow-scrolling:touch}
  .post-nav a{padding:13px}
  .related-posts{margin-top:26px}
}
@media (max-width:620px){
  .wrap{padding-inline:14px}
  .top .wrap{height:58px}
  .top.nav-open .main-nav{top:58px;padding:8px 14px}
  .toolbar{top:58px}
  .hero{padding:16px 14px}
  .hero-art{height:86px}
  /* The two densest lists become two columns to reduce scroll length. */
  #Label1 .widget-content > ul,
  #BlogArchive1 .widget-content > ul{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));column-gap:14px;align-items:start}
  #Label1 .widget-content > ul > li,
  #BlogArchive1 .widget-content > ul > li{min-width:0;overflow-wrap:anywhere}
  #Label1 .label-name{display:flex;align-items:baseline;justify-content:space-between;gap:5px;width:100%}
  #Label1 .label-count{flex:0 0 auto;font-size:.78em}
  .to-top{right:12px;bottom:12px;width:40px;height:40px}
  .toast{bottom:12px}
  .related-posts-grid{grid-template-columns:minmax(0,1fr)}
}
/* Embedded media and long unbroken strings must never widen the viewport. */
.post-body,.post-body > *{min-width:0;max-width:100%}
.post-body pre,.post-body pre code{max-width:100%}
.post-body img,.post-body video,.post-body iframe,.post-body embed{max-width:100%}
.post-body pre code{display:block;overflow-x:auto}
/* Strong keyboard focus and practical touch targets. */
button,.tool-btn,.main-nav a,.hero-topics a,.post-labels a,.sidebar li a{touch-action:manipulation}
.nav-toggle,.icon-btn,.tool-btn,.copy-code{min-height:40px}
.sidebar li a{min-height:28px}
@media (prefers-contrast:more){
  :root,:root[data-theme="dark"],:root[data-theme="oled"]{--muted:#b5c2bc;--border-strong:#64756d}
  a{ text-decoration-thickness: .08em; }
}
.related-posts{margin-top:34px;padding-top:20px;border-top:1px solid var(--border)}
.related-posts h2{margin:0 0 12px;font-size:1.1rem}
.related-posts-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}
.related-post-card{display:flex;flex-direction:column;gap:7px;min-width:0;padding:13px;border:1px solid var(--border);border-radius:12px;background:var(--surface);color:var(--text)}
.related-post-card:hover{border-color:var(--accent)}
.related-post-card time{color:var(--muted);font-size:.78rem}
.related-posts-status{color:var(--muted);font-size:.88rem}
/* Highlight.js styles are only activated if an article actually has code. */
.post-body pre code.hljs{display:block;padding:0;background:transparent;color:inherit}
/* ---------- Mobile sidebar cleanup (overrides the earlier 620px rules) ---------- */
@media (max-width:620px){
  .layout{padding-bottom:40px}
  .sidebar{display:flex;flex-direction:column;gap:14px;padding-bottom:76px}
  .sidebar .widget{margin:0;padding:16px;background:var(--surface);box-shadow:none;border-radius:14px}
  .sidebar h2.title{margin:0 0 10px;font-size:.95rem}
  .sidebar .widget-content > ul{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));column-gap:16px;row-gap:0;margin:0}
  .sidebar .widget-content > ul > li{padding:8px 0;border-bottom:0;min-width:0;overflow-wrap:anywhere;font-size:.9rem}
  .sidebar .label-count,.sidebar .post-count{margin-left:6px}
  .pop-item{padding:10px 0}
}
/* Static pages (quest): the widget already shows the title, so hide the duplicate post heading */
body.static_page .article h1{display:none}
body.static_page .article .crumbs,body.static_page .article .article-meta,body.static_page .article .share-top{display:none!important}
/* Quest page: no sidebar, full-width column, focus-style layout */
body.static_page .sidebar{display:none!important}
body.static_page .layout{grid-template-columns:minmax(0,1fr)!important}
body.static_page .article{max-width:var(--max)!important}

body.script:
//
(function(){
  var d=document, root=d.documentElement, win=window;
  var S=win.AS, DEFAULTS=win.AS_DEFAULTS;
  var pageUrl=win.location.href.split('#')[0], pageTitle=d.title;
  var enc=encodeURIComponent;

  function clamp(v,a,b){ return Math.max(a,Math.min(b,v)); }
  function save(){ try{ localStorage.setItem('as-settings',JSON.stringify(S)); }catch(e){} }

  /* Reflect current settings in every control (aria-pressed drives the chip styling) */
  function sync(){
    d.querySelectorAll('[data-set]').forEach(function(btn){
      btn.setAttribute('aria-pressed',String(S[btn.getAttribute('data-set')]===btn.getAttribute('data-value')));
    });
    d.querySelectorAll('[data-toggle]').forEach(function(btn){
      btn.setAttribute('aria-pressed',String(!!S[btn.getAttribute('data-toggle')]));
    });
    var readout=d.getElementById('size-readout');
    if(readout) readout.textContent=S.size+'%';
    var colorInput=d.getElementById('custom-accent');
    if(colorInput) colorInput.value=S.custom;
    var focusBtn=d.getElementById('focus-toggle');
    if(focusBtn) focusBtn.setAttribute('aria-pressed',String(!!S.focus));
    var tb=d.getElementById('theme-toggle');
    if(tb) tb.setAttribute('aria-label',(S.theme==='light'||S.theme==='paper')?'Switch to dark theme':'Switch to light theme');
  }
  function change(key,value){ S[key]=value; save(); win.AS_APPLY(S); sync(); }

  /* Toast (textContent only, never HTML) */
  var toastEl=d.getElementById('toast'), toastTimer=null;
  function toast(msg){
    if(!toastEl) return;
    toastEl.textContent=msg; toastEl.classList.add('show');
    clearTimeout(toastTimer);
    toastTimer=setTimeout(function(){ toastEl.classList.remove('show'); },2000);
  }

  /* Clipboard with fallback */
  function fallbackCopy(value,done){
    var f=d.createElement('textarea');
    f.value=value; f.setAttribute('readonly',''); f.style.position='fixed'; f.style.opacity='0';
    d.body.appendChild(f); f.select();
    var ok=false; try{ ok=d.execCommand('copy'); }catch(e){}
    f.remove();
    if(ok){ if(done) done(); } else toast('Copy is unavailable here');
  }
  function copyText(value,done){
    if(navigator.clipboard && navigator.clipboard.writeText){
      navigator.clipboard.writeText(value).then(done).catch(function(){ fallbackCopy(value,done); });
    } else fallbackCopy(value,done);
  }

  /* Mobile nav: toggle, and close after choosing a link */
  var header=d.getElementById('top'), navBtn=d.getElementById('nav-toggle');
  if(navBtn) navBtn.addEventListener('click',function(){
    var open=header.classList.toggle('nav-open');
    navBtn.setAttribute('aria-expanded',open?'true':'false');
  });
  d.querySelectorAll('#main-nav a').forEach(function(a){
    a.addEventListener('click',function(){
      header.classList.remove('nav-open');
      if(navBtn) navBtn.setAttribute('aria-expanded','false');
    });
  });

  /* Header theme toggle: flips between dark and light */
  var themeBtn=d.getElementById('theme-toggle');
  if(themeBtn) themeBtn.addEventListener('click',function(){
    change('theme',(S.theme==='light'||S.theme==='paper')?'dark':'light');
  });

  /* Search shortcut: "/" focuses the search box, Escape leaves it */
  var q=d.getElementById('q');
  d.addEventListener('keydown',function(e){
    var tag=(d.activeElement&&d.activeElement.tagName)||'';
    if(e.key==='/' && q && !/INPUT|TEXTAREA/.test(tag)){ e.preventDefault(); q.focus(); }
    if(e.key==='Escape' && q && d.activeElement===q){ q.blur(); }
  });

  /* Reading progress bar + back to top */
  var toTop=d.getElementById('to-top'), bar=d.getElementById('reading-progress-bar');
  function onScroll(){
    if(toTop) toTop.classList.toggle('show',win.scrollY>600);
    if(bar){
      var max=root.scrollHeight-win.innerHeight;
      bar.style.width=(max>0?Math.min(100,win.scrollY/max*100):0)+'%';
    }
  }
  win.addEventListener('scroll',onScroll,{passive:true});
  win.addEventListener('resize',onScroll);
  onScroll();
  if(toTop) toTop.addEventListener('click',function(){ win.scrollTo({top:0,behavior:'smooth'}); });

  /* Pause ambient motion when the tab is hidden */
  d.addEventListener('visibilitychange',function(){ root.classList.toggle('is-hidden',d.hidden); });

  /* Focus mode */
  var focusBtn=d.getElementById('focus-toggle');
  if(focusBtn) focusBtn.addEventListener('click',function(){ change('focus',!S.focus); });

  /* Display settings panel */
  var panel=d.getElementById('settings'), panelBtn=d.getElementById('settings-toggle');
  function openPanel(on){
    panel.hidden=!on;
    panelBtn.setAttribute('aria-expanded',on?'true':'false');
    if(on){ var first=panel.querySelector('button'); if(first) first.focus(); }
  }
  panelBtn.addEventListener('click',function(){ openPanel(panel.hidden); });
  d.getElementById('settings-close').addEventListener('click',function(){ openPanel(false); panelBtn.focus(); });
  d.addEventListener('keydown',function(e){
    if(e.key==='Escape' && !panel.hidden){ openPanel(false); panelBtn.focus(); }
  });
  d.addEventListener('click',function(e){
    if(!panel.hidden && !panel.contains(e.target) && !panelBtn.contains(e.target)) openPanel(false);
  });

  /* Option chips: data-set="key" data-value="value" */
  panel.querySelectorAll('[data-set]').forEach(function(btn){
    btn.addEventListener('click',function(){
      change(btn.getAttribute('data-set'),btn.getAttribute('data-value'));
    });
  });
  /* Toggles: data-toggle="key" */
  panel.querySelectorAll('[data-toggle]').forEach(function(btn){
    btn.addEventListener('click',function(){
      var key=btn.getAttribute('data-toggle');
      change(key,!S[key]);
    });
  });
  /* Text size stepper */
  panel.querySelectorAll('[data-step]').forEach(function(btn){
    btn.addEventListener('click',function(){
      change('size',clamp(S.size+parseInt(btn.getAttribute('data-step'),10),85,130));
    });
  });
  /* Custom accent */
  var customInput=d.getElementById('custom-accent');
  customInput.addEventListener('input',function(){
    S.custom=customInput.value; S.accent='custom';
    save(); win.AS_APPLY(S); sync();
  });
  /* Reading mode preset */
  d.getElementById('reading-mode').addEventListener('click',function(){
    S.theme='paper'; S.font='serif'; S.measure='narrow';
    S.focus=true; S.bg='solid'; S.motion='off';
    save(); win.AS_APPLY(S); sync();
  });
  /* Reset everything */
  d.getElementById('settings-reset').addEventListener('click',function(){
    for(var k in DEFAULTS){ if(Object.prototype.hasOwnProperty.call(DEFAULTS,k)) S[k]=DEFAULTS[k]; }
    save(); win.AS_APPLY(S); sync();
  });

  /* Hero cursor glow: fine pointers only, and only when motion is on */
  var hero=d.querySelector('.hero');
  if(hero && win.matchMedia && win.matchMedia('(pointer:fine)').matches){
    hero.addEventListener('pointermove',function(e){
      if(S.motion==='off') return;
      var r=hero.getBoundingClientRect();
      hero.style.setProperty('--mx',((e.clientX-r.left)/r.width*100)+'%');
      hero.style.setProperty('--my',((e.clientY-r.top)/r.height*100)+'%');
    });
  }

  /* Share row: icon-only buttons, one builder for the site bar and article slots */
  var ICONS={
    x:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" aria-hidden="true"><path d="M4 4l16 16M20 4L4 20"/></svg>',
    facebook:'<svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M14 8V6.5c0-.8.4-1.2 1.2-1.2H17V2h-2.6C11.9 2 11 3.6 11 5.6V8H8.5v3.5H11V22h3V11.5h2.6l.4-3.5H14z"/></svg>',
    linkedin:'<svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><rect x="3" y="9" width="4" height="12"/><circle cx="5" cy="5" r="2.2"/><path d="M10 9h3.8v1.7c.6-1.1 2-2 4-2 3.6 0 4.2 2.3 4.2 5.4V21h-4v-6.1c0-1.5 0-3.3-2-3.3s-2.3 1.6-2.3 3.2V21h-4z"/></svg>',
    whatsapp:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linejoin="round" aria-hidden="true"><path d="M4 20l1.3-4.1A8 8 0 1 1 8.2 18.8L4 20z"/></svg>',
    telegram:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linejoin="round" aria-hidden="true"><path d="M21 4L3 11l6 2.2L11.5 20l3-4.5 5.5 4z"/></svg>',
    reddit:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><circle cx="12" cy="13.5" r="7.5"/><circle cx="9.5" cy="13" r=".8" fill="currentColor"/><circle cx="14.5" cy="13" r=".8" fill="currentColor"/><path d="M9 16.5c1.8 1.2 4.2 1.2 6 0M15 5l1 3.5 3.5.5M13 3.5l-1 4"/></svg>',
    threads:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" aria-hidden="true"><circle cx="12" cy="12" r="3.5"/><path d="M15.5 12v1.2a2.8 2.8 0 0 0 5.5 0V12a9 9 0 1 0-3.6 7.2"/></svg>',
    pinterest:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linejoin="round" aria-hidden="true"><path d="M12 21.5s-7-5.6-7-11.2a7 7 0 0 1 14 0c0 5.6-7 11.2-7 11.2z"/><circle cx="12" cy="10.3" r="2.4"/></svg>',
    email:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linejoin="round" aria-hidden="true"><rect x="3" y="5" width="18" height="14" rx="2"/><path d="M3.5 6.5l8.5 6 8.5-6"/></svg>',
    instagram:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><rect x="3" y="3" width="18" height="18" rx="5"/><circle cx="12" cy="12" r="4"/><circle cx="17.5" cy="6.5" r=".6" fill="currentColor"/></svg>',
    more:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M4 12v7a1 1 0 0 0 1 1h14a1 1 0 0 0 1-1v-7M16 6l-4-4-4 4M12 2v13"/></svg>',
    copy:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" aria-hidden="true"><path d="M10 14a4 4 0 0 0 5.7 0l3-3a4 4 0 0 0-5.7-5.7l-1 1M14 10a4 4 0 0 0-5.7 0l-3 3a4 4 0 0 0 5.7 5.7l1-1"/></svg>'
  };
  var targets=[
    {name:'X',         icon:'x',         href:'https://x.com/intent/post?url='+enc(pageUrl)+'&text='+enc(pageTitle)},
    {name:'Facebook',  icon:'facebook',  href:'https://www.facebook.com/sharer/sharer.php?u='+enc(pageUrl)},
    {name:'LinkedIn',  icon:'linkedin',  href:'https://www.linkedin.com/sharing/share-offsite/?url='+enc(pageUrl)},
    {name:'WhatsApp',  icon:'whatsapp',  href:'https://wa.me/?text='+enc(pageTitle+' '+pageUrl)},
    {name:'Telegram',  icon:'telegram',  href:'https://t.me/share/url?url='+enc(pageUrl)+'&text='+enc(pageTitle)},
    {name:'Reddit',    icon:'reddit',    href:'https://www.reddit.com/submit?url='+enc(pageUrl)+'&title='+enc(pageTitle)},
    {name:'Threads',   icon:'threads',   href:'https://www.threads.net/intent/post?text='+enc(pageTitle+' '+pageUrl)},
    {name:'Pinterest', icon:'pinterest', href:'https://pinterest.com/pin/create/button/?url='+enc(pageUrl)+'&description='+enc(pageTitle)},
    {name:'Email',     icon:'email',     href:'mailto:?subject='+enc(pageTitle)+'&body='+enc(pageUrl)}
  ];
  function iconButton(el,name,icon){
    el.className=(el.className?el.className+' ':'')+'ic';
    el.innerHTML=ICONS[icon];
    el.setAttribute('aria-label',name);
    el.title=name;
    return el;
  }
  function buildShare(slot){
    var label=d.createElement('span');
    label.className='share-label'; label.textContent='Share';
    slot.appendChild(label);
    targets.forEach(function(t){
      var a=d.createElement('a');
      a.href=t.href; a.target='_blank'; a.rel='noopener noreferrer';
      slot.appendChild(iconButton(a,t.name,t.icon));
    });
    /* Instagram has no web share URL, so copy the link for pasting */
    var ig=d.createElement('button');
    ig.type='button';
    iconButton(ig,'Instagram','instagram');
    ig.addEventListener('click',function(){
      copyText(pageUrl,function(){ toast('Link copied. Paste it into your Instagram story or caption.'); });
    });
    slot.appendChild(ig);
    if(navigator.share){
      var nat=d.createElement('button');
      nat.type='button';
      iconButton(nat,'Share using your device','more');
      nat.addEventListener('click',function(){ navigator.share({title:pageTitle,url:pageUrl}).catch(function(){}); });
      slot.appendChild(nat);
    }
    var copy=d.createElement('button');
    copy.type='button';
    iconButton(copy,'Copy link','copy');
    copy.addEventListener('click',function(){ copyText(pageUrl,function(){ toast('Link copied'); }); });
    slot.appendChild(copy);
  }
  d.querySelectorAll('[data-share-slot]').forEach(buildShare);

  /* Article-only features */
  var article=d.getElementById('article'), body=d.getElementById('post-body');
  if(article && body){
    var words=(body.innerText||'').trim().split(/\s+/).filter(Boolean).length;
    var rt=d.getElementById('reading-time');
    if(rt) rt.textContent='· '+Math.max(1,Math.ceil(words/220))+' min read';

    /* Local reading list: saved in this browser only */
    var saveBtn=d.getElementById('save-article');
    var savedKey='as-reading-list';
    function readSaved(){
      try{ var v=JSON.parse(localStorage.getItem(savedKey)||'[]'); return Array.isArray(v)?v:[]; }
      catch(e){ return []; }
    }
    function indexOfPage(items){
      return items.findIndex(function(item){ return item && item.url===pageUrl; });
    }
    function paintSaved(isSaved){
      if(!saveBtn) return;
      saveBtn.setAttribute('aria-pressed',isSaved?'true':'false');
      saveBtn.textContent=isSaved?'★ Saved':'☆ Save';
      saveBtn.title=isSaved?'Remove from your reading list':'Save to your reading list';
    }
    paintSaved(indexOfPage(readSaved())!==-1);
    if(saveBtn) saveBtn.addEventListener('click',function(){
      var items=readSaved(), i=indexOfPage(items);
      if(i!==-1){ items.splice(i,1); paintSaved(false); toast('Removed from your reading list'); }
      else { items.unshift({url:pageUrl,title:pageTitle,savedAt:new Date().toISOString()}); items=items.slice(0,200); paintSaved(true); toast('Saved on this device'); }
      try{ localStorage.setItem(savedKey,JSON.stringify(items)); }
      catch(e){ toast('Browser storage is unavailable'); }
    });

    var printBtn=d.getElementById('print-btn');
    if(printBtn) printBtn.addEventListener('click',function(){ win.print(); });

    /* Table of contents */
    var heads=Array.prototype.slice.call(body.querySelectorAll('h2,h3'));
    heads.forEach(function(h,i){ if(!h.id) h.id='section-'+(i+1); });
    if(heads.length>=3){
      var toc=d.createElement('details'); toc.className='article-toc'; toc.open=true;
      var sum=d.createElement('summary'); sum.textContent='On this page';
      var ol=d.createElement('ol'), links={};
      toc.appendChild(sum);
      heads.forEach(function(h){
        var li=d.createElement('li'), a=d.createElement('a');
        if(h.tagName==='H3') li.style.marginLeft='12px';
        a.href='#'+h.id; a.textContent=h.textContent.trim();
        links[h.id]=a; li.appendChild(a); ol.appendChild(li);
      });
      toc.appendChild(ol);
      body.parentNode.insertBefore(toc,body);
      if('IntersectionObserver' in win){
        var io=new IntersectionObserver(function(entries){
          entries.forEach(function(en){
            if(!en.isIntersecting) return;
            Object.keys(links).forEach(function(k){ links[k].classList.toggle('is-active',k===en.target.id); });
          });
        },{rootMargin:'-15% 0px -70% 0px'});
        heads.forEach(function(h){ io.observe(h); });
      }
    }

    /* Code blocks: copy button */
    body.querySelectorAll('pre').forEach(function(pre){
      var btn=d.createElement('button');
      btn.type='button'; btn.className='copy-code'; btn.textContent='Copy';
      btn.addEventListener('click',function(){
        var code=pre.querySelector('code')||pre;
        copyText(code.textContent,function(){
          btn.textContent='Copied'; setTimeout(function(){ btn.textContent='Copy'; },1400);
        });
      });
      pre.appendChild(btn);
    });

    /* Optional syntax highlighting: load only on article pages that contain code. */
    var codeBlocks=body.querySelectorAll('pre code');
    if(codeBlocks.length){
      var hlCss=d.createElement('link');
      hlCss.rel='stylesheet';
      hlCss.href='https://cdn.jsdelivr.net/npm/highlight.js@11.11.1/styles/github-dark.min.css';
      hlCss.media='print'; hlCss.onload=function(){hlCss.media='all';};
      d.head.appendChild(hlCss);
      var hlScript=d.createElement('script');
      hlScript.src='https://cdn.jsdelivr.net/npm/highlight.js@11.11.1/highlight.min.js';
      hlScript.defer=true;
      hlScript.onload=function(){
        if(!win.hljs) return;
        codeBlocks.forEach(function(code){
          if(!code.classList.contains('language-text') && !code.classList.contains('nohighlight')){
            try{win.hljs.highlightElement(code);}catch(e){}
          }
        });
      };
      d.head.appendChild(hlScript);
    }

    /* Related articles: use the first existing Blogger label; fail quietly if feeds are unavailable. */
    var labelLink=d.querySelector('.post-labels a[rel="tag"]');
    if(labelLink && win.fetch){
      var relatedSection=d.createElement('section');
      relatedSection.className='related-posts';
      relatedSection.setAttribute('aria-labelledby','related-posts-title');
      var relatedTitle=d.createElement('h2');
      relatedTitle.id='related-posts-title'; relatedTitle.textContent='Related articles';
      var relatedGrid=d.createElement('div'); relatedGrid.className='related-posts-grid';
      relatedSection.appendChild(relatedTitle); relatedSection.appendChild(relatedGrid);
      var labelsWrap=d.querySelector('.post-labels');
      if(labelsWrap && labelsWrap.parentNode) labelsWrap.parentNode.insertBefore(relatedSection,labelsWrap.nextSibling);
      var labelPath=labelLink.getAttribute('href');
      try{
        var labelUrl=new URL(labelPath,win.location.href);
        var feedUrl=new URL('/feeds/posts/default/-/'+encodeURIComponent(labelLink.textContent.trim()),win.location.origin);
        feedUrl.searchParams.set('alt','json'); feedUrl.searchParams.set('max-results','6');
        if(labelUrl.origin===win.location.origin){
          fetch(feedUrl.href,{credentials:'same-origin'}).then(function(resp){
            if(!resp.ok) throw new Error('feed unavailable'); return resp.json();
          }).then(function(json){
            var entries=json && json.feed && json.feed.entry ? json.feed.entry : [];
            var added=0;
            entries.forEach(function(entry){
              if(added>=4 || !entry || !entry.link) return;
              var alt=entry.link.find(function(link){return link.rel==='alternate' && link.href;});
              var title=entry.title && entry.title.$t;
              if(!alt || !title || alt.href.split('#')[0]===pageUrl) return;
              var card=d.createElement('a'); card.className='related-post-card'; card.href=alt.href;
              var name=d.createElement('strong'); name.textContent=title; card.appendChild(name);
              if(entry.published && entry.published.$t){
                var date=d.createElement('time');
                var dt=new Date(entry.published.$t);
                if(!isNaN(dt.getTime())){date.dateTime=dt.toISOString();date.textContent=dt.toLocaleDateString(undefined,{year:'numeric',month:'short',day:'numeric'});card.appendChild(date);}
              }
              relatedGrid.appendChild(card); added++;
            });
            if(!added) relatedSection.remove();
          }).catch(function(){relatedSection.remove();});
        } else relatedSection.remove();
      }catch(e){relatedSection.remove();}
    }

    /* External links open in a new tab, without leaking the opener */
    body.querySelectorAll('a[href]').forEach(function(a){
      if(/^https?:/i.test(a.getAttribute('href')) && a.hostname!==win.location.hostname){
        a.target='_blank'; a.rel='noopener noreferrer';
      }
    });

    /* Image lightbox (native dialog: Escape closes it) */
    body.querySelectorAll('img').forEach(function(img){
      img.loading='lazy';
      img.addEventListener('click',function(){
        var dlg=d.createElement('dialog'); dlg.className='lightbox';
        dlg.setAttribute('aria-label',img.alt||'Image preview');
        var big=d.createElement('img'); big.src=img.currentSrc||img.src; big.alt=img.alt||'';
        dlg.appendChild(big); d.body.appendChild(dlg);
        dlg.addEventListener('click',function(){ dlg.close(); });
        dlg.addEventListener('close',function(){ dlg.remove(); });
        dlg.showModal();
      });
    });
  }

  /* Static pages: move the comments section below the quest widget.
     Climbs from the quest to its direct child of #main-col so extra
     Blogger wrappers do not matter. Logs what it found to help debug. */
  (function(){
    var quest = d.getElementById('quest') || d.getElementById('agentic');
    var cmts  = d.getElementById('comments') || d.querySelector('section.comments');
    if(!quest || !cmts){ console.log('comments move: quest=', !!quest, 'comments=', !!cmts); return; }
    var host = quest;
    while(host.parentNode && host.parentNode.id !== 'main-col'){ host = host.parentNode; }
    if(host.parentNode){ host.parentNode.insertBefore(cmts, host.nextSibling); }
  })();

  /* Apply saved state to every control */
  sync();
})();
//
